"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[62228],{46508:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Constructs a new JSONTranslator from the given args.\\n\\n```lua\\nlocal translator = JSONTranslator.new(\\"MyTranslator\\", \\"en\\", {\\n\\tactions = {\\n\\t\\trespawn = \\"Respawn {playerName}\\";\\n\\t};\\n})\\n\\nprint(translator:FormatByKey(\\"actions.respawn\\"), { playerName = \\"Quenty\\"}) --\x3e Respawn Quenty\\n\\n-- Observing is preferred\\nmaid:GiveTask(translator:ObserveFormatByKey(\\"actions.respawn\\", {\\n\\tplayerName = RxInstanceUtils.observeProperty(player, \\"DisplayName\\");\\n}):Subscribe(function(text)\\n\\tprint(text) --\x3e \\"Respawn Quenty\\"\\nend))\\n```\\n\\n```lua\\nlocal translator = JSONTranslator.new(script)\\n-- assume there is an `en.json` underneath the script with valid JSON.\\n```","params":[{"name":"translatorName","desc":"Name of the translator. Used for source.","lua_type":"string"},{"name":"localeId","desc":"","lua_type":"string"},{"name":"dataTable","desc":"","lua_type":"table"}],"returns":[{"desc":"","lua_type":"JSONTranslator"}],"function_type":"static","source":{"line":100,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"ObserveFormatByKey","desc":"Observes the translated value, re-emitting as the locale changes and as the key\'s data\\nbecomes readable.\\n\\nEmits immediately on subscribe with the best text available rather than withholding, so a\\nbound label is never blank for a frame. Until a key\'s data has landed that best text may be\\nthe source language, or the translation key itself for a key registered this frame; the\\ncorrect translation replaces it once the key is readable. It will not go the other way: a\\nlocale swap never replaces good text with a fallback.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"translationArgs","desc":"May have observables (or convertable to observables) in it.","lua_type":"table?"}],"returns":[{"desc":"","lua_type":"Observable<string>"}],"function_type":"static","source":{"line":210,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"PromiseFormatByKey","desc":"Formats the resulting entry by args.\\n\\n:::tip\\nYou should use [JSONTranslator.ObserveFormatByKey] instead of this to respond\\nto locale changing.\\n:::","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"args","desc":"","lua_type":"table?"}],"returns":[{"desc":"","lua_type":"Promise<string>"}],"function_type":"static","source":{"line":256,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"_observeTranslationReady","desc":"Observes when a translation key is readable for the current locale, emitting the locale\\nid it is readable for, or nil while its data is still queued.\\n\\n:::warning\\nThis is an implementation detail, exposed for the translation stack itself and for\\ndiagnostics. You should not need it: every way of reading a translation\\n([JSONTranslator.ObserveFormatByKey], [JSONTranslator.PromiseFormatByKey],\\n[JSONTranslator.FormatByKey], [JSONTranslator.ObserveTranslation]) already waits for the\\nkey it reads, and re-reads when a locale swap brings new data in.\\n:::\\n\\nLocalization writes are batched to the end of the frame (see\\n[TranslatorService.SetEntryValue]), because a game streaming in can register thousands of\\nentries in a single frame and each raw table write invalidates every AutoLocalize entry\\nin the engine. That means a key is not readable the instant it is registered, and this is\\nhow the read paths above find out that it is.\\n\\nRe-emits whenever the locale changes or new data lands for the key, so a locale swap is\\npicked up without resubscribing. Nothing here yields.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"translationKey","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Observable<string?>"}],"function_type":"static","source":{"line":300,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"PromiseTranslator","desc":"Returns a promise that will resolve once the Roblox translator is loaded from the cloud.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[{"desc":"","lua_type":"Promise<Translator>"}],"function_type":"static","source":{"line":365,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"ObserveTranslator","desc":"Observes the current Roblox translator for this translator.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[{"desc":"","lua_type":"Observable<Translator>"}],"function_type":"static","source":{"line":374,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"ObserveLocaleId","desc":"Observes the current locale id for this translator.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[{"desc":"","lua_type":"Observable<string>"}],"function_type":"static","source":{"line":383,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"SetEntryValue","desc":"Adds an entry value to the localization table itself. This can be useful\\nfor ensuring pseudo localization and/or generating localization values\\nfrom the game data itself.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"source","desc":"","lua_type":"string"},{"name":"context","desc":"","lua_type":"string"},{"name":"localeId","desc":"","lua_type":"string"},{"name":"text","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":398,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"ObserveTranslation","desc":"Observes a translation key and formats it with the given args.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"prefix","desc":"","lua_type":"string"},{"name":"text","desc":"","lua_type":"string"},{"name":"translationArgs","desc":"","lua_type":"table?"}],"returns":[{"desc":"","lua_type":"Observable<string>"}],"function_type":"static","source":{"line":433,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"ToTranslationKey","desc":"Converts the given prefix and text into a translation key.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"prefix","desc":"","lua_type":"string"},{"name":"text","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":452,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"GetLocaleId","desc":"Gets the current localeId of the translator if it\'s initialized, or a default if it is not.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":470,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"GetLocalizationTable","desc":"Gets the localization table the translation is using.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[{"desc":"","lua_type":"LocalizationTable"}],"function_type":"static","source":{"line":479,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"PromiseLoaded","desc":"Returns a promise that will resolve once the translator is loaded from the cloud.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[{"desc":"","lua_type":"Promise"}],"function_type":"static","source":{"line":487,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"FormatByKey","desc":"Formats or errors if the cloud translations are not loaded.\\n\\n:::tip\\nYou should use [JSONTranslator.ObserveFormatByKey] instead of this to respond\\nto locale changing.\\n:::\\n\\nQueues the current locale\'s entries if they are not loaded yet, so a first synchronous read\\nof a locale costs that decode; the observable path pays the same cost on subscribe.","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"args","desc":"","lua_type":"table?"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":506,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}},{"name":"Destroy","desc":"Cleans up the translator and deletes the localization table if it exists.\\nShould be called by [ServiceBag]","params":[{"name":"self","desc":"","lua_type":"JSONTranslator"}],"returns":[],"function_type":"static","source":{"line":626,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}}],"properties":[],"types":[],"name":"JSONTranslator","desc":"Utility function that loads a translator from a folder or a table.\\n\\nTo get translations uploaded.\\n\\n1. Run the game\\n2. On the client, check LocalizationService.GeneratedJSONTable\\n3. Right click > Save as CSV\\n4. Stop the game\\n5. In Studio, go to plugins > \\"Localization Tools\\"\\n6. Upload the CSV (update)","source":{"line":16,"path":"src/clienttranslator/src/Shared/JSONTranslator.lua"}}')}}]);